import{_ as e,o,c as a,l as t,t as r,N as s}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse('{"title":"docker-container-kill | x-cmd man (docker man1) | Kill one or more running containers","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-container-kill - Kill one or more running containers","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-container-kill | x-cmd man (docker man1) | Kill one or more running containers"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-container-kill - Kill one or more running containers"}]]},"headers":[],"params":{"isMan":true,"man":"docker-container-kill","category":"docker man1","desc":"Kill one or more running containers"},"relativePath":"docker/man1/docker-container-kill.md","filePath":"docker/man1/docker-container-kill.md"}'),i={name:"docker/man1/docker-container-kill.md"},l={class:"visually-hidden"},c=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-container-kill - Kill one or more running containers</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker container kill [OPTIONS] CONTAINER [CONTAINER...]</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>docker kill</strong> subcommand kills one or more containers. The main process inside the container is sent <strong>SIGKILL</strong> signal (default), or the signal that is specified with the <strong>--signal</strong> option. You can reference a container by its ID, ID-prefix, or name.</p><p>The <strong>--signal</strong> flag sets the system call signal that is sent to the container. This signal can be a signal name in the format <strong>SIG&lt;NAME&gt;</strong>, for instance <strong>SIGINT</strong>, or an unsigned number that matches a position in the kernel&#39;s syscall table, for instance <strong>2</strong>.</p><p>While the default (<strong>SIGKILL</strong>) signal will terminate the container, the signal set through <strong>--signal</strong> may be non-terminal, depending on the container&#39;s main process. For example, the <strong>SIGHUP</strong> signal in most cases will be non-terminal, and the container will continue running after receiving the signal.</p><blockquote><p><strong>Note</strong></p><p><strong>ENTRYPOINT</strong> and <strong>CMD</strong> in the <em>shell</em> form run as a child process of <strong>/bin/sh -c</strong>, which does not pass signals. This means that the executable is not the container&#39;s PID 1 and does not receive Unix signals.</p></blockquote><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-h</strong>, <strong>--help</strong>[=false] help for kill</p><p><strong>-s</strong>, <strong>--signal</strong>=&quot;&quot; Signal to send to the container</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-container(1)</strong></p>',14);function g(n,d,h,m,p,k){return o(),a("div",null,[t("h1",l,r(n.$params.man),1),c])}const S=e(i,[["render",g]]);export{f as __pageData,S as default};
